<title>LT 2010 · Computer Skills for the Information Age</title>
<style>
  /* ============================================================
     LT 2010 — "Field notes for the Information Age"
     Serif = the human voice · Mono = the machine / structure
     ============================================================ */

  :root {
    /* type */
    --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, "Times New Roman", serif;
    --mono: ui-monospace, "SF Mono", "SFMono-Regular", "Cascadia Code", Menlo, Consolas, monospace;

    /* color — light (warm paper, indigo ink, cobalt structure, amber time) */
    --paper: #f6f3ec;
    --surface: #fffdf8;
    --surface-2: #efeade;
    --ink: #1a1d29;
    --ink-soft: #3d4356;
    --muted: #6d7386;
    --line: #ddd6c7;
    --line-strong: #c9c1ae;
    --cobalt: #2b52cf;
    --cobalt-ink: #21419f;
    --cobalt-wash: #e7ecfb;
    --amber: #a86a0c;
    --amber-wash: #f4e7c9;
    --shadow: 22px 22px 60px -40px rgba(26, 29, 41, .45);

    --measure: 66ch;
    --page: 940px;
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --paper: #12141c;
      --surface: #191c26;
      --surface-2: #20232f;
      --ink: #ece8dd;
      --ink-soft: #bcc0d0;
      --muted: #868ba0;
      --line: #2a2e3c;
      --line-strong: #3a3f50;
      --cobalt: #8ba4ff;
      --cobalt-ink: #a9bcff;
      --cobalt-wash: #1c2340;
      --amber: #e2ab55;
      --amber-wash: #2c2413;
      --shadow: 22px 22px 70px -44px rgba(0, 0, 0, .8);
    }
  }
  /* explicit toggle must win both directions */
  :root[data-theme="light"] {
    --paper: #f6f3ec; --surface: #fffdf8; --surface-2: #efeade;
    --ink: #1a1d29; --ink-soft: #3d4356; --muted: #6d7386;
    --line: #ddd6c7; --line-strong: #c9c1ae;
    --cobalt: #2b52cf; --cobalt-ink: #21419f; --cobalt-wash: #e7ecfb;
    --amber: #a86a0c; --amber-wash: #f4e7c9;
    --shadow: 22px 22px 60px -40px rgba(26, 29, 41, .45);
  }
  :root[data-theme="dark"] {
    --paper: #12141c; --surface: #191c26; --surface-2: #20232f;
    --ink: #ece8dd; --ink-soft: #bcc0d0; --muted: #868ba0;
    --line: #2a2e3c; --line-strong: #3a3f50;
    --cobalt: #8ba4ff; --cobalt-ink: #a9bcff; --cobalt-wash: #1c2340;
    --amber: #e2ab55; --amber-wash: #2c2413;
    --shadow: 22px 22px 70px -44px rgba(0, 0, 0, .8);
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    background: var(--paper);
    color: var(--ink);
    font-family: var(--serif);
    font-size: 18px;
    line-height: 1.62;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  /* subtle graph-paper wash — a quiet nod to information design */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    background-image:
      linear-gradient(var(--line) 1px, transparent 1px),
      linear-gradient(90deg, var(--line) 1px, transparent 1px);
    background-size: 30px 30px;
    opacity: .28;
    -webkit-mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 0%, transparent 78%);
    mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 0%, transparent 78%);
  }

  .wrap {
    position: relative;
    z-index: 1;
    max-width: var(--page);
    margin: 0 auto;
    padding: clamp(28px, 6vw, 76px) clamp(20px, 5vw, 56px) 96px;
  }

  /* ---- shared type utilities ---- */
  .mono {
    font-family: var(--mono);
    font-feature-settings: "tnum" 1;
  }
  .eyebrow {
    font-family: var(--mono);
    font-size: .72rem;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--cobalt);
    margin: 0;
  }
  .tnum { font-variant-numeric: tabular-nums; }

  a { color: var(--cobalt); text-underline-offset: 3px; text-decoration-thickness: 1px; }
  a:hover { color: var(--cobalt-ink); }
  :focus-visible { outline: 2.5px solid var(--cobalt); outline-offset: 3px; border-radius: 2px; }

  /* ============================ MASTHEAD ============================ */
  .masthead {
    border-bottom: 1.5px solid var(--ink);
    padding-bottom: 28px;
    margin-bottom: 40px;
  }
  .masthead .topline {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 16px;
    flex-wrap: wrap;
    font-family: var(--mono);
    font-size: .74rem;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--muted);
  }
  .masthead .topline .code { color: var(--cobalt); font-weight: 600; }
  .masthead h1 {
    font-size: clamp(2.5rem, 7vw, 4.6rem);
    line-height: 1.02;
    letter-spacing: -.015em;
    font-weight: 600;
    margin: .38em 0 .18em;
    text-wrap: balance;
    max-width: 15ch;
  }
  .masthead .lede {
    font-size: clamp(1.08rem, 2.4vw, 1.3rem);
    color: var(--ink-soft);
    font-style: italic;
    max-width: 46ch;
    margin: 0;
  }
  .masthead .facts {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 10px;
    margin-top: 26px;
    list-style: none;
    padding: 0;
  }
  .masthead .facts li {
    font-family: var(--mono);
    font-size: .72rem;
    letter-spacing: .06em;
    text-transform: uppercase;
    color: var(--ink-soft);
    background: var(--surface);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 6px 13px;
  }
  .masthead .facts li b { color: var(--cobalt); font-weight: 600; }

  /* ============================ SECTIONS ============================ */
  section { margin-top: 68px; scroll-margin-top: 24px; }
  .sec-head {
    display: flex;
    align-items: baseline;
    gap: 16px;
    margin-bottom: 26px;
  }
  .sec-head .num {
    font-family: var(--mono);
    font-size: .78rem;
    color: var(--cobalt);
    letter-spacing: .1em;
    padding-top: .5em;
  }
  .sec-head h2 {
    font-size: clamp(1.5rem, 3.4vw, 2.1rem);
    font-weight: 600;
    letter-spacing: -.01em;
    margin: 0;
    text-wrap: balance;
  }
  .sec-head .rule {
    flex: 1;
    height: 1px;
    background: var(--line-strong);
    align-self: center;
  }

  .prose p { max-width: var(--measure); color: var(--ink-soft); }
  .prose p.intro {
    font-size: 1.16rem;
    color: var(--ink);
    max-width: var(--measure);
  }

  /* learning goals grid */
  .goals {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 2px;
    margin-top: 30px;
    border: 1px solid var(--line-strong);
    background: var(--line-strong);
    border-radius: 12px;
    overflow: hidden;
  }
  .goals .goal {
    background: var(--surface);
    padding: 20px 22px;
  }
  .goals .goal .g-n {
    font-family: var(--mono);
    font-size: .72rem;
    color: var(--cobalt);
    letter-spacing: .12em;
  }
  .goals .goal p { margin: 8px 0 0; font-size: .98rem; color: var(--ink); max-width: none; }

  /* ===================== AT-A-GLANCE / GRADING ===================== */
  .glance {
    display: grid;
    grid-template-columns: 1.15fr .85fr;
    gap: 34px;
    background: var(--surface);
    border: 1px solid var(--line-strong);
    border-radius: 16px;
    padding: clamp(24px, 4vw, 38px);
    box-shadow: var(--shadow);
  }
  @media (max-width: 720px) { .glance { grid-template-columns: 1fr; gap: 30px; } }

  .glance h3 {
    font-family: var(--mono);
    font-size: .74rem;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--muted);
    margin: 0 0 18px;
    font-weight: 500;
  }

  /* grade bars */
  .grades { display: flex; flex-direction: column; gap: 15px; }
  .grade-row { display: grid; grid-template-columns: 1fr auto; gap: 4px 14px; align-items: baseline; }
  .grade-row .label { font-size: 1rem; }
  .grade-row .pct {
    font-family: var(--mono);
    font-weight: 600;
